UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites arithmétiques et géométriques","subtitle_fr":"Raison additive ou multiplicative, formules.","sections":[{"kind":"concept","title_fr":"Définitions","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"**Arithmétique** : on ajoute toujours la même raison $r$. **Géométrique** : on multiplie toujours par la même raison $q$."},{"kind":"formula","latex":"u_n = u_0 + n r \\quad \\text{(arithm.)}, \\qquad u_n = u_0 \\cdot q^n \\quad \\text{(géom.)}","caption_fr":"Termes généraux."},{"kind":"formula","latex":"S_\\text{arithm} = (n+1) \\frac{u_0 + u_n}{2}, \\qquad S_\\text{géom} = u_0 \\frac{1 - q^{n+1}}{1-q}","caption_fr":"Sommes."},{"kind":"example","title_fr":"Croissance bactérienne","problem_fr":"Une colonie double toutes les heures, départ 100 bactéries. Effectif à t=5h ?","steps_fr":["Géométrique $q=2$, $u_0 = 100$.","$u_5 = 100 \\cdot 32 = 3200$ bactéries."],"answer_fr":"3200 bactéries."},{"kind":"checkpoint","title_fr":"Suites","questions":[{"stem_fr":"Raison de $3, 7, 11, 15$ :","choices_fr":["2","3","4","5"],"correct_index":2,"explanation_fr":"Différence constante 4."},{"stem_fr":"$u_0=1$, $q=3$, alors $u_4$ :","choices_fr":["12","27","81","243"],"correct_index":2,"explanation_fr":"$1 \\cdot 3^4 = 81$."},{"stem_fr":"Somme $1+2+\\dots+20$ :","choices_fr":["100","200","210","400"],"correct_index":2,"explanation_fr":"$20 \\times 21/2 = 210$."}]}]}]}'::jsonb WHERE code = 'svt_arith_geom_seq';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Calcul de limites","subtitle_fr":"Substitution, factorisation, infini.","sections":[{"kind":"concept","title_fr":"Méthodes","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Substitution directe** si $f$ continue. Si on tombe sur $0/0$, factoriser et simplifier."},{"kind":"paragraph","md":"**À l''infini** : pour un quotient de polynômes, regarder le rapport des termes dominants."},{"kind":"formula","latex":"\\lim_{x \\to +\\infty} \\frac{e^x}{x^n} = +\\infty, \\quad \\lim_{x \\to +\\infty} \\frac{\\ln x}{x} = 0","caption_fr":"Croissances comparées (à mémoriser)."},{"kind":"example","title_fr":"Forme 0/0","problem_fr":"$\\lim_{x \\to 2} (x^2 - 4)/(x - 2)$","steps_fr":["Factoriser : $(x-2)(x+2)/(x-2) = x+2$.","Limite = $2+2 = 4$."],"answer_fr":"4."},{"kind":"checkpoint","title_fr":"Limites","questions":[{"stem_fr":"$\\lim_{x \\to 0} \\sin x/x$ :","choices_fr":["0","1","π","∞"],"correct_index":1,"explanation_fr":"Limite usuelle."},{"stem_fr":"$\\lim_{x \\to +\\infty} 1/x^2$ :","choices_fr":["0","1","∞","n''existe pas"],"correct_index":0,"explanation_fr":"$1/x^\\alpha \\to 0$ pour $\\alpha > 0$."},{"stem_fr":"$\\lim_{x \\to +\\infty} (3x^2)/(x^2+1)$ :","choices_fr":["0","1","3","∞"],"correct_index":2,"explanation_fr":"Coeff dominants."}]}]}]}'::jsonb WHERE code = 'svt_limit_calc';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Dérivation et applications","subtitle_fr":"Règles, variations, extrema.","sections":[{"kind":"concept","title_fr":"Règles de dérivation","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"(x^n)'' = n x^{n-1}, \\quad (\\sqrt x)'' = \\frac{1}{2\\sqrt x}, \\quad (\\sin x)'' = \\cos x, \\quad (e^x)'' = e^x, \\quad (\\ln x)'' = 1/x","caption_fr":"Dérivées usuelles."},{"kind":"formula","latex":"(uv)'' = u''v + uv'', \\quad (u/v)'' = (u''v - uv'')/v^2, \\quad (f \\circ g)''(x) = f''(g(x)) g''(x)","caption_fr":"Produit, quotient, composition."}]},{"kind":"concept","title_fr":"Variations et extrema","eyebrow_fr":"APPLICATIONS","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Le **signe de $f''$** donne le sens de variation : $f'' > 0$ → croissante, $f'' < 0$ → décroissante."},{"kind":"paragraph","md":"Aux **extrema locaux**, $f'' = 0$ (tangente horizontale)."},{"kind":"checkpoint","title_fr":"Dérivation","questions":[{"stem_fr":"Dérivée de $3x^2 - x + 5$ :","choices_fr":["$6x$","$6x - 1$","$3x - 1$","$6x + 5$"],"correct_index":1,"explanation_fr":"Linéarité, $(x^2)'' = 2x$."},{"stem_fr":"Si $f'' > 0$, $f$ est :","choices_fr":["constante","croissante","décroissante","maximale"],"correct_index":1,"explanation_fr":"Dérivée positive → croissance."},{"stem_fr":"À un max local : $f''(x_0) = ?$","choices_fr":["1","0","∞","indéfini"],"correct_index":1,"explanation_fr":"Tangente horizontale."}]}]}]}'::jsonb WHERE code = 'svt_deriv_apps';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Fonctions exponentielle et logarithme","subtitle_fr":"Propriétés algébriques, croissances comparées.","sections":[{"kind":"concept","title_fr":"Définitions et propriétés","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"$\\exp(x) = e^x$ est définie sur $\\mathbb{R}$, à valeurs dans $]0, +\\infty[$. **Réciproque** : $\\ln$, définie sur $]0, +\\infty[$."},{"kind":"formula","latex":"e^a \\cdot e^b = e^{a+b}, \\quad \\ln(ab) = \\ln a + \\ln b, \\quad \\ln(e^x) = x","caption_fr":"Propriétés clés."},{"kind":"formula","latex":"(e^x)'' = e^x, \\quad (\\ln x)'' = 1/x","caption_fr":"Dérivées."},{"kind":"formula","latex":"\\lim_{x \\to +\\infty} e^x/x = +\\infty, \\quad \\lim_{x \\to +\\infty} \\ln x/x = 0","caption_fr":"Croissances comparées."}]},{"kind":"concept","title_fr":"Application en SVT — décroissance","eyebrow_fr":"APPLICATION","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"**Modèle exponentiel** : utilisé pour la radioactivité, la pharmacocinétique, la décroissance d''une population de bactéries dans un milieu hostile."},{"kind":"formula","latex":"N(t) = N_0 e^{-\\lambda t}","caption_fr":"Décroissance exponentielle, demi-vie $t_{1/2} = \\ln 2/\\lambda$."},{"kind":"checkpoint","title_fr":"Exp et ln","questions":[{"stem_fr":"$\\ln(e^2)$ vaut :","choices_fr":["0","1","2","$e^2$"],"correct_index":2,"explanation_fr":"$\\ln(e^x) = x$."},{"stem_fr":"$e^0$ vaut :","choices_fr":["0","1","$e$","∞"],"correct_index":1,"explanation_fr":"Définition."},{"stem_fr":"Demi-vie d''une décroissance $N_0 e^{-\\lambda t}$ :","choices_fr":["$1/\\lambda$","$\\ln 2/\\lambda$","$\\lambda \\ln 2$","$2\\lambda$"],"correct_index":1,"explanation_fr":"$t_{1/2} = \\ln 2/\\lambda$."}]}]}]}'::jsonb WHERE code = 'svt_exp_ln_combined';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Primitives et intégrales (bases)","subtitle_fr":"Définition, calcul, aires.","sections":[{"kind":"concept","title_fr":"Primitives et intégrale","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"$F$ est primitive de $f$ si $F'' = f$. Deux primitives diffèrent d''une constante."},{"kind":"formula","latex":"\\int_a^b f(x)\\,dx = F(b) - F(a)","caption_fr":"**Newton-Leibniz**."},{"kind":"formula","latex":"\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C, \\quad \\int e^x\\,dx = e^x + C, \\quad \\int 1/x\\,dx = \\ln|x| + C","caption_fr":"Primitives usuelles."},{"kind":"example","title_fr":"Calcul d''aire","problem_fr":"Aire sous $y = x^2$ entre 0 et 3.","steps_fr":["$\\int_0^3 x^2\\,dx = [x^3/3]_0^3 = 9$."],"answer_fr":"9."},{"kind":"checkpoint","title_fr":"Intégrales","questions":[{"stem_fr":"Primitive de $2x$ :","choices_fr":["$2$","$x^2$","$x$","$2 x^2$"],"correct_index":1,"explanation_fr":"$(x^2)'' = 2x$."},{"stem_fr":"$\\int_0^1 1\\,dx$ vaut :","choices_fr":["0","1","x","C"],"correct_index":1,"explanation_fr":"Aire d''un rectangle 1×1."},{"stem_fr":"$\\int_1^e 1/x\\,dx$ :","choices_fr":["0","1","$e$","$e-1$"],"correct_index":1,"explanation_fr":"$[\\ln x]_1^e = 1$."}]}]}]}'::jsonb WHERE code = 'svt_integral_basics';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Lois de Newton et applications","subtitle_fr":"Inertie, F = ma, action-réaction.","sections":[{"kind":"concept","title_fr":"Les trois lois","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**1ère loi (inertie)** : un objet isolé est au repos ou en MRU."},{"kind":"formula","latex":"\\sum \\vec F = m \\vec a","caption_fr":"**2ème loi** : force totale = masse × accélération."},{"kind":"paragraph","md":"**3ème loi (action-réaction)** : forces toujours par paires opposées."},{"kind":"example","title_fr":"Plan incliné","problem_fr":"Bloc 5 kg sur plan à 30° (sans frottement). Accélération ? (g=10)","steps_fr":["Selon le plan : $m a = m g \\sin 30°$.","$a = g \\sin 30° = 5\\,\\text{m/s}^2$."],"answer_fr":"5 m/s²."},{"kind":"checkpoint","title_fr":"Newton","questions":[{"stem_fr":"Si $\\sum \\vec F = \\vec 0$, l''objet :","choices_fr":["accélère","repos ou MRU","tombe","tourne"],"correct_index":1,"explanation_fr":"1ère loi."},{"stem_fr":"Force = ?","choices_fr":["$m v$","$m a$","$m g$","$m h$"],"correct_index":1,"explanation_fr":"2ème loi."},{"stem_fr":"Unité de la force :","choices_fr":["$\\text{kg}$","$\\text{N}$","$\\text{J}$","$\\text{W}$"],"correct_index":1,"explanation_fr":"Newton."}]}]}]}'::jsonb WHERE code = 'svt_newton_apps';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Énergie mécanique","subtitle_fr":"Cinétique, potentielle, conservation.","sections":[{"kind":"concept","title_fr":"Formes et conservation","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"E_c = \\frac{1}{2} m v^2, \\quad E_p = m g h, \\quad E_m = E_c + E_p","caption_fr":"Énergies."},{"kind":"paragraph","md":"**Sans frottement** : $E_m$ est **conservée**. Avec frottements : $E_m$ diminue (chaleur)."},{"kind":"example","title_fr":"Chute libre","problem_fr":"Pierre lâchée d''une hauteur $h$. Vitesse en bas ?","steps_fr":["Conservation : $mgh = \\frac{1}{2} m v^2 \\iff v = \\sqrt{2 g h}$."],"answer_fr":"$v = \\sqrt{2 g h}$."},{"kind":"checkpoint","title_fr":"Énergie","questions":[{"stem_fr":"$E_c$ d''un objet 2 kg à 5 m/s :","choices_fr":["5 J","10 J","25 J","50 J"],"correct_index":2,"explanation_fr":"$(1/2)(2)(25) = 25$."},{"stem_fr":"Sans frottement, $E_m$ :","choices_fr":["augmente","décroît","constante","= 0"],"correct_index":2,"explanation_fr":"Conservation."},{"stem_fr":"Vitesse au sol pour h=5m, g=10 :","choices_fr":["10 m/s","$\\sqrt{100}$=10 m/s","50 m/s","5 m/s"],"correct_index":0,"explanation_fr":"$v = \\sqrt{2 \\cdot 10 \\cdot 5} = 10$."}]}]}]}'::jsonb WHERE code = 'svt_energy';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Ondes mécaniques et lumineuses","subtitle_fr":"Propagation, célérité, longueur d''onde.","sections":[{"kind":"concept","title_fr":"Grandeurs","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une **onde** transporte de l''énergie sans transporter de matière. **Transversale** (corde) ou **longitudinale** (son)."},{"kind":"formula","latex":"\\lambda = v T = v/f","caption_fr":"Relation fondamentale."},{"kind":"paragraph","md":"Le **son** se propage dans tout milieu matériel (gaz, liquide, solide). La **lumière** se propage aussi dans le vide (c = 3×10⁸ m/s)."},{"kind":"checkpoint","title_fr":"Ondes","questions":[{"stem_fr":"Relation longueur d''onde / fréquence :","choices_fr":["$\\lambda = vf$","$\\lambda = v/f$","$\\lambda = f/v$","$\\lambda = v - f$"],"correct_index":1,"explanation_fr":"$\\lambda = v T = v/f$."},{"stem_fr":"Le son est :","choices_fr":["transversal","longitudinal","EM","optique"],"correct_index":1,"explanation_fr":"Compressions/raréfactions."},{"stem_fr":"Célérité de la lumière dans le vide :","choices_fr":["340 m/s","$3 \\times 10^8$ m/s","$1500$ m/s","$10^{10}$ m/s"],"correct_index":1,"explanation_fr":"Constante c."}]}]}]}'::jsonb WHERE code = 'svt_waves';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Radioactivité et datation","subtitle_fr":"Désintégrations, demi-vie, datation par C14.","sections":[{"kind":"concept","title_fr":"Désintégrations","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un noyau radioactif se désintègre en émettant : $\\alpha$ (noyau d''hélium), $\\beta^-$ (électron), $\\beta^+$ (positron), ou $\\gamma$ (photon)."},{"kind":"paragraph","md":"**Lois de conservation** : nombre de masse $A$ et numéro atomique $Z$ totaux préservés."},{"kind":"formula","latex":"N(t) = N_0 e^{-\\lambda t}, \\quad t_{1/2} = \\ln 2/\\lambda","caption_fr":"Loi de décroissance et demi-vie."},{"kind":"example","title_fr":"Datation au C14","problem_fr":"Échantillon à 12,5% de l''activité initiale. Âge ? (t½ = 5730 ans)","steps_fr":["$1/8 = 1/2^3$ → 3 demi-vies écoulées.","Âge = 3 × 5730 = 17 190 ans."],"answer_fr":"≈ 17 200 ans."},{"kind":"checkpoint","title_fr":"Radioactivité","questions":[{"stem_fr":"Émission alpha = particule :","choices_fr":["$^1_1H$","$^4_2He$","$^0_{-1}e$","$\\gamma$"],"correct_index":1,"explanation_fr":"Noyau d''hélium-4."},{"stem_fr":"Après 2 demi-vies, il reste :","choices_fr":["1/2","1/4","1/8","0"],"correct_index":1,"explanation_fr":"$N_0/2^2 = N_0/4$."},{"stem_fr":"Demi-vie en fonction de $\\lambda$ :","choices_fr":["$1/\\lambda$","$\\ln 2/\\lambda$","$\\lambda^2$","$2\\lambda$"],"correct_index":1,"explanation_fr":"$t_{1/2} = \\ln 2/\\lambda$."}]}]}]}'::jsonb WHERE code = 'svt_radioactivity_basics';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Dipôle RC","subtitle_fr":"Charge et décharge d''un condensateur.","sections":[{"kind":"concept","title_fr":"Charge et décharge","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un condensateur stocke de la charge électrique. Associé à une résistance $R$, son régime transitoire est **exponentiel**."},{"kind":"formula","latex":"\\tau = R C, \\quad u_C^\\text{charge}(t) = E(1 - e^{-t/\\tau}), \\quad u_C^\\text{décharge}(t) = U_0 e^{-t/\\tau}","caption_fr":"Constante de temps et solutions."},{"kind":"formula","latex":"E_C = \\frac{1}{2} C u_C^2","caption_fr":"Énergie stockée."},{"kind":"checkpoint","title_fr":"Dipôle RC","questions":[{"stem_fr":"Constante de temps :","choices_fr":["$R + C$","$R/C$","$RC$","$1/(RC)$"],"correct_index":2,"explanation_fr":"$\\tau = RC$ (en secondes)."},{"stem_fr":"À $t = 5\\tau$, le condensateur est chargé à :","choices_fr":["50%","63%","95%",">99%"],"correct_index":3,"explanation_fr":"Régime établi."},{"stem_fr":"Énergie d''un condensateur :","choices_fr":["$CU$","$CU^2$","$(1/2) CU^2$","$U/C$"],"correct_index":2,"explanation_fr":"Formule standard."}]}]}]}'::jsonb WHERE code = 'svt_rc_circuit';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"pH et solutions","subtitle_fr":"Acides, bases, autoprotolyse de l''eau.","sections":[{"kind":"concept","title_fr":"pH et acidité","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"pH = -\\log[\\text{H}_3\\text{O}^+], \\quad K_e = [\\text{H}_3\\text{O}^+][\\text{OH}^-] = 10^{-14} \\,(25°C)","caption_fr":"Définition et autoprotolyse."},{"kind":"paragraph","md":"**Acide** : pH < 7 ($[\\text{H}_3\\text{O}^+] > [\\text{OH}^-]$). **Basique** : pH > 7. **Neutre** : pH = 7 à 25°C."},{"kind":"paragraph","md":"**Acide fort** : totalement dissocié → $pH = -\\log C$. **Acide faible** : équilibre, pKa caractéristique."},{"kind":"checkpoint","title_fr":"pH","questions":[{"stem_fr":"pH d''une solution d''acide fort à 0,01 mol/L :","choices_fr":["1","2","7","12"],"correct_index":1,"explanation_fr":"$-\\log 10^{-2} = 2$."},{"stem_fr":"pH d''une solution neutre :","choices_fr":["0","7","10","14"],"correct_index":1,"explanation_fr":"À 25°C."},{"stem_fr":"Si $pH = 9$, $[\\text{OH}^-]$ vaut :","choices_fr":["$10^{-9}$","$10^{-5}$","$10^{-14}$","$9$"],"correct_index":1,"explanation_fr":"$[\\text{H}_3\\text{O}^+] = 10^{-9}$, $[\\text{OH}^-] = 10^{-5}$."}]}]}]}'::jsonb WHERE code = 'svt_ph';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Oxydoréduction et piles","subtitle_fr":"Couples redox, transferts d''électrons.","sections":[{"kind":"concept","title_fr":"Couples et demi-équations","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Oxydation** : perte d''électrons. **Réduction** : gain d''électrons. Couples notés $Ox/Red$."},{"kind":"formula","latex":"\\text{Cu}^{2+} + 2 e^- \\to \\text{Cu}, \\quad \\text{Zn} \\to \\text{Zn}^{2+} + 2 e^-","caption_fr":"Demi-équations (Cu²⁺/Cu et Zn²⁺/Zn)."},{"kind":"paragraph","md":"**Pile** : 2 demi-piles reliées par un pont salin. Oxydation à l''anode (-), réduction à la cathode (+)."},{"kind":"formula","latex":"Q = I \\cdot t = n_e \\cdot F, \\quad F = 96\\,500\\,\\text{C/mol}","caption_fr":"Quantité d''électricité (Faraday)."},{"kind":"checkpoint","title_fr":"Redox","questions":[{"stem_fr":"Oxydation = ?","choices_fr":["gain e⁻","perte e⁻","gain H⁺","perte H⁺"],"correct_index":1,"explanation_fr":"Définition."},{"stem_fr":"À l''anode d''une pile :","choices_fr":["réduction","oxydation","rien","décomposition"],"correct_index":1,"explanation_fr":"An-Ox."},{"stem_fr":"fem de la pile Daniell :","choices_fr":["0,1 V","1,1 V","11 V","0 V"],"correct_index":1,"explanation_fr":"Cu - Zn = 0,34 - (-0,76) = 1,10 V."}]}]}]}'::jsonb WHERE code = 'svt_redox_basics';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Chimie organique — esters","subtitle_fr":"Estérification, hydrolyse, saponification.","sections":[{"kind":"concept","title_fr":"Esters et leur formation","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\text{R-COOH} + \\text{R''-OH} \\rightleftharpoons \\text{R-COO-R''} + \\text{H}_2\\text{O}","caption_fr":"Estérification (sens →) / hydrolyse (sens ←)."},{"kind":"paragraph","md":"**Lente, limitée, athermique** (K ≈ 4). On peut déplacer l''équilibre : excès de réactif, ou élimination d''eau."},{"kind":"paragraph","md":"**Saponification** : ester + base forte → carboxylate + alcool, **totale**. Procédé industriel pour les savons."},{"kind":"paragraph","md":"**Importance biologique** : les **triglycérides** (graisses) sont des **triesters** d''acides gras et de glycérol."},{"kind":"checkpoint","title_fr":"Esters","questions":[{"stem_fr":"Estérification :","choices_fr":["rapide","lente et limitée","totale","exothermique forte"],"correct_index":1,"explanation_fr":"Caractéristiques."},{"stem_fr":"Saponification = ester + ?","choices_fr":["eau","acide","base forte","sucre"],"correct_index":2,"explanation_fr":"Réaction totale."},{"stem_fr":"Effet de T sur estérification (équilibre) :","choices_fr":["favorise","défavorise","aucun (athermique)","annule"],"correct_index":2,"explanation_fr":"ΔH ≈ 0."}]}]}]}'::jsonb WHERE code = 'svt_organic_basics';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Génétique humaine — lois de Mendel","subtitle_fr":"Monohybridisme, dihybridisme, hérédité.","sections":[{"kind":"concept","title_fr":"Vocabulaire et 1ère loi","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Gène** : segment d''ADN codant un caractère. **Allèles** : versions d''un même gène (ex : couleur des yeux bleus/marrons). **Génotype** : ensemble des allèles. **Phénotype** : caractère observable."},{"kind":"paragraph","md":"Un individu est **homozygote** si ses deux allèles sont identiques (AA ou aa), **hétérozygote** sinon (Aa). L''allèle **dominant** s''exprime même chez l''hétérozygote ; le **récessif** ne s''exprime que chez l''homozygote."},{"kind":"paragraph","md":"**1ère loi de Mendel (uniformité)** : croisement entre deux lignées pures → F1 100% **hétérozygote**, phénotype dominant uniforme."}]},{"kind":"concept","title_fr":"2ème loi et 3ème loi","eyebrow_fr":"LOIS","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**2ème loi (ségrégation)** : croisement F1 × F1 → F2 phénotypiquement **3:1** (3 dominants pour 1 récessif). Génotypique : 1 AA : 2 Aa : 1 aa."},{"kind":"paragraph","md":"**3ème loi (assortiment indépendant)** : pour deux gènes sur **chromosomes différents**, en F2 dihybride : **9:3:3:1** (dominant×dominant : dominant×récessif : récessif×dominant : récessif×récessif)."},{"kind":"example","title_fr":"Monohybridisme","problem_fr":"Croisement AA × aa. Proportions en F2 ?","steps_fr":["F1 : 100% Aa (phénotype dominant).","F2 (Aa × Aa) : 1 AA : 2 Aa : 1 aa → phénotypes 3 dominants : 1 récessif."],"answer_fr":"3:1 phénotypique."},{"kind":"checkpoint","title_fr":"Mendel","questions":[{"stem_fr":"F1 d''un croisement AA × aa :","choices_fr":["AA","aa","Aa","mélangé"],"correct_index":2,"explanation_fr":"Tous hétérozygotes."},{"stem_fr":"Ratio phénotypique F2 monohybride :","choices_fr":["1:1","3:1","9:3:3:1","1:2:1"],"correct_index":1,"explanation_fr":"2ème loi."},{"stem_fr":"Ratio F2 dihybride (gènes indépendants) :","choices_fr":["1:1","3:1","9:3:3:1","1:2:1"],"correct_index":2,"explanation_fr":"3ème loi."}]}]}]}'::jsonb WHERE code = 'svt_genetique_humaine';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Génétique des populations — Hardy-Weinberg","subtitle_fr":"Fréquences alléliques, équilibre génétique.","sections":[{"kind":"concept","title_fr":"Loi de Hardy-Weinberg","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Pour un gène à 2 allèles $A$ et $a$ de fréquences $p$ et $q$ (avec $p + q = 1$), les fréquences génotypiques à l''équilibre sont :"},{"kind":"formula","latex":"f(AA) = p^2, \\quad f(Aa) = 2pq, \\quad f(aa) = q^2","caption_fr":"Loi de Hardy-Weinberg."},{"kind":"callout","tone":"warning","title_fr":"Conditions de validité","body_fr":"Population grande, pas de sélection, pas de mutation, pas de migration, accouplement au hasard. Toute déviation indique une force évolutive à l''œuvre."}]},{"kind":"concept","title_fr":"Calculs","eyebrow_fr":"EXEMPLES","estimated_minutes":"4","blocks":[{"kind":"example","title_fr":"Allèle récessif","problem_fr":"Dans une population, 4% des individus sont $aa$. Fréquence de $a$ ?","steps_fr":["$f(aa) = q^2 = 0{,}04$ → $q = 0{,}2$.","Fréquence de $A$ : $p = 0{,}8$.","Hétérozygotes : $2 p q = 0{,}32 = 32\\%$."],"answer_fr":"$q = 0{,}2$."},{"kind":"checkpoint","title_fr":"Hardy-Weinberg","questions":[{"stem_fr":"Si $p = 0{,}5$, fréquence des hétérozygotes :","choices_fr":["0,25","0,5","0,75","1"],"correct_index":1,"explanation_fr":"$2 \\times 0{,}5 \\times 0{,}5 = 0{,}5$."},{"stem_fr":"$f(AA) + f(Aa) + f(aa)$ vaut :","choices_fr":["p","q","1","pq"],"correct_index":2,"explanation_fr":"Total des fréquences."},{"stem_fr":"Une dérive génétique violerait :","choices_fr":["pas de sélection","population grande","panmixie","pas de migration"],"correct_index":1,"explanation_fr":"Dérive = effet hasard, fort en petite pop."}]}]}]}'::jsonb WHERE code = 'svt_genetique_populations';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Diversification génétique — méiose et brassage","subtitle_fr":"Méiose, brassages interchromosomique et intrachromosomique.","sections":[{"kind":"concept","title_fr":"Méiose","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"La **méiose** est une double division cellulaire qui produit **4 gamètes haploïdes (n)** à partir d''une cellule diploïde (2n). Étapes : prophase I (appariement des chromosomes homologues), métaphase I, anaphase I (séparation des homologues), puis méiose II (comme une mitose)."},{"kind":"paragraph","md":"Le **brassage interchromosomique** se produit en métaphase/anaphase I : chaque paire d''homologues s''oriente **au hasard**. Pour $n$ paires, on obtient $2^n$ combinaisons (chez l''homme, $n=23$ → $2^{23} \\approx 8 \\times 10^6$ combinaisons)."}]},{"kind":"concept","title_fr":"Brassage intrachromosomique et fécondation","eyebrow_fr":"COMBINAISONS","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Le **brassage intrachromosomique** (crossing-over) se produit en prophase I : les chromatides homologues échangent des fragments. Génère de nouvelles combinaisons d''allèles sur le même chromosome."},{"kind":"paragraph","md":"**Fécondation** : combine au hasard 1 gamète femelle parmi $2^{23}$ avec 1 gamète mâle parmi $2^{23}$ → $2^{46} \\approx 7 \\times 10^{13}$ combinaisons. Plus le crossing-over → diversité quasi-infinie."},{"kind":"checkpoint","title_fr":"Diversification","questions":[{"stem_fr":"La méiose produit :","choices_fr":["2 cellules 2n","2 cellules n","4 cellules n","4 cellules 2n"],"correct_index":2,"explanation_fr":"4 gamètes haploïdes."},{"stem_fr":"Brassage interchromosomique se produit :","choices_fr":["prophase I","anaphase I","prophase II","télophase II"],"correct_index":1,"explanation_fr":"Séparation aléatoire des homologues."},{"stem_fr":"Crossing-over (intrachromosomique) :","choices_fr":["prophase I","anaphase I","métaphase II","mitose"],"correct_index":0,"explanation_fr":"Appariement et échange en prophase I."}]}]}]}'::jsonb WHERE code = 'svt_diversification_genetique';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Mécanismes de l''évolution","subtitle_fr":"Sélection naturelle, dérive, mutations, spéciation.","sections":[{"kind":"concept","title_fr":"Forces évolutives","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Mutations** : modifications aléatoires de l''ADN. **Source ultime** de la variation génétique (rare mais inéluctable)."},{"kind":"paragraph","md":"**Sélection naturelle** (Darwin) : les individus les mieux adaptés à leur environnement survivent et se reproduisent davantage → leurs allèles sont sur-représentés à la génération suivante. C''est **non aléatoire**."},{"kind":"paragraph","md":"**Dérive génétique** : variation aléatoire des fréquences alléliques due à l''échantillonnage à chaque génération. Effet majeur dans les **petites populations**."},{"kind":"paragraph","md":"**Migration** (flux génique) : échange d''allèles entre populations."}]},{"kind":"concept","title_fr":"Spéciation","eyebrow_fr":"NOUVELLES ESPÈCES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"La **spéciation** est l''émergence d''une nouvelle espèce. Le critère le plus utilisé : **isolement reproductif** (deux populations ne peuvent plus produire de descendants fertiles)."},{"kind":"paragraph","md":"**Modes** : (1) **allopatrique** (séparation géographique → divergence indépendante), (2) **sympatrique** (au sein d''une même zone, par spécialisation écologique ou polyploïdie)."},{"kind":"callout","tone":"insight","title_fr":"Exemple emblématique","body_fr":"Les pinsons des Galápagos (Darwin) : 13 espèces dérivées d''un ancêtre commun, différenciées par la forme du bec selon l''alimentation disponible sur chaque île."},{"kind":"checkpoint","title_fr":"Évolution","questions":[{"stem_fr":"Source ultime de la variation génétique :","choices_fr":["sélection","mutations","reproduction","environnement"],"correct_index":1,"explanation_fr":"Seules les mutations créent de nouveaux allèles."},{"stem_fr":"La dérive génétique est :","choices_fr":["déterministe","aléatoire","sélective","environnementale"],"correct_index":1,"explanation_fr":"Effet du hasard à petite échelle."},{"stem_fr":"Spéciation allopatrique implique :","choices_fr":["mutations","séparation géographique","polyploïdie","rien"],"correct_index":1,"explanation_fr":"Isolement par barrière géo."}]}]}]}'::jsonb WHERE code = 'svt_evolution';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Communication nerveuse","subtitle_fr":"Neurone, potentiel d''action, synapse.","sections":[{"kind":"concept","title_fr":"Le neurone et le PA","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un **neurone** est composé d''un corps cellulaire (soma), de dendrites (entrée d''information) et d''un axone (sortie). Long de quelques µm à plus de 1 m."},{"kind":"paragraph","md":"**Au repos** : différence de potentiel transmembranaire d''environ $-70\\,\\text{mV}$ (intérieur négatif). Maintenue par la pompe Na⁺/K⁺ et les canaux ioniques."},{"kind":"paragraph","md":"**Potentiel d''action (PA)** : inversion brusque de polarité (de -70 à environ +40 mV) qui se propage le long de l''axone. **Loi du tout ou rien** : déclenché si stimulation atteint un seuil, sinon rien."},{"kind":"paragraph","md":"**Codage de l''information** : par la **fréquence** des PA (et non leur amplitude, fixe). Plus le stimulus est fort, plus la fréquence est élevée."}]},{"kind":"concept","title_fr":"La synapse","eyebrow_fr":"TRANSMISSION","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"À la jonction entre deux neurones (ou neurone-effecteur), la **synapse** transmet l''information. Le PA présynaptique provoque la libération de **neurotransmetteurs** (acétylcholine, dopamine, GABA...) dans la fente synaptique."},{"kind":"paragraph","md":"Les neurotransmetteurs se fixent sur des récepteurs postsynaptiques → nouveau PA ou inhibition selon le type."},{"kind":"callout","tone":"insight","title_fr":"Vitesse de propagation","body_fr":"Sans gaine de myéline : ~1 m/s. Avec myéline (propagation saltatoire de nœud en nœud de Ranvier) : jusqu''à 100 m/s. Sclérose en plaques = perte de myéline → ralentissement neuronal."},{"kind":"checkpoint","title_fr":"Communication nerveuse","questions":[{"stem_fr":"Potentiel de repos d''un neurone :","choices_fr":["+70 mV","0 mV","-70 mV","+40 mV"],"correct_index":2,"explanation_fr":"Intérieur négatif."},{"stem_fr":"Codage de l''intensité du stimulus :","choices_fr":["amplitude du PA","durée du PA","fréquence des PA","forme du PA"],"correct_index":2,"explanation_fr":"Loi du tout ou rien."},{"stem_fr":"À la synapse, transmission par :","choices_fr":["électricité directe","neurotransmetteurs","ondes","aucun"],"correct_index":1,"explanation_fr":"Synapse chimique."}]}]}]}'::jsonb WHERE code = 'svt_communication_nerveuse';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Communication hormonale","subtitle_fr":"Glandes endocrines, régulation, rétrocontrôle.","sections":[{"kind":"concept","title_fr":"Hormones et glandes","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Une **hormone** est une molécule sécrétée par une **glande endocrine** dans le sang, qui agit sur des **cellules-cibles** distantes possédant des récepteurs spécifiques."},{"kind":"paragraph","md":"**Glandes principales** : hypothalamus, hypophyse (cheffe d''orchestre), thyroïde (thyroxine — métabolisme), surrénales (adrénaline, cortisol — stress), pancréas (insuline/glucagon — glycémie), gonades (testostérone/œstrogènes — reproduction)."}]},{"kind":"concept","title_fr":"Régulation par rétrocontrôle","eyebrow_fr":"BOUCLE","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Rétrocontrôle négatif** : la sortie d''un système inhibe son entrée → stabilisation. Exemple : la glycémie augmente → insuline sécrétée → glycémie baisse → insuline diminue."},{"kind":"paragraph","md":"**Axe hypothalamo-hypophyso-cible** : l''hypothalamus libère des neurohormones qui agissent sur l''hypophyse, qui libère des hormones agissant sur des glandes cibles (thyroïde, surrénales, gonades). La cible exerce un rétrocontrôle sur l''hypothalamus/hypophyse."},{"kind":"example","title_fr":"Régulation glycémique","problem_fr":"Glycémie haute. Mécanisme de régulation ?","steps_fr":["Pancréas (cellules β) détecte la hausse → libère de l''**insuline**.","L''insuline fait entrer le glucose dans les cellules (foie, muscle) → glycémie baisse.","La baisse → réduction de l''insuline. Rétrocontrôle négatif."],"answer_fr":"Insuline → diminution de glycémie."},{"kind":"checkpoint","title_fr":"Hormones","questions":[{"stem_fr":"L''insuline est sécrétée par :","choices_fr":["foie","pancréas","thyroïde","surrénales"],"correct_index":1,"explanation_fr":"Cellules β des îlots de Langerhans."},{"stem_fr":"Rétrocontrôle négatif :","choices_fr":["amplifie","stabilise","inverse","détruit"],"correct_index":1,"explanation_fr":"Sortie inhibe l''entrée."},{"stem_fr":"Le diabète de type 1 est dû à :","choices_fr":["excès d''insuline","manque d''insuline","manque de glucose","excès de glucagon"],"correct_index":1,"explanation_fr":"Cellules β détruites → pas d''insuline."}]}]}]}'::jsonb WHERE code = 'svt_communication_hormonale';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Immunité innée et acquise","subtitle_fr":"Défense de l''organisme, vaccination.","sections":[{"kind":"concept","title_fr":"Deux lignes de défense","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Immunité innée** (immédiate, non-spécifique) : barrières (peau, muqueuses), réaction inflammatoire, phagocytes (macrophages, neutrophiles), système du complément. Réagit en quelques heures, sans mémoire."},{"kind":"paragraph","md":"**Immunité acquise** (différée, spécifique) : intervient si l''innée ne suffit pas. Deux voies :"},{"kind":"paragraph","md":"- **Humorale (LB)** : les lymphocytes B produisent des **anticorps** spécifiques qui neutralisent les antigènes.\n- **Cellulaire (LT)** : les lymphocytes T cytotoxiques détruisent les cellules infectées."}]},{"kind":"concept","title_fr":"Mémoire et vaccination","eyebrow_fr":"PROTECTION","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Après une première rencontre avec un antigène, des **cellules mémoire** persistent. Lors d''un second contact, la réponse est **plus rapide et plus intense** → protection."},{"kind":"paragraph","md":"**Vaccination** : on injecte un antigène atténué ou inactivé → réponse immunitaire **sans la maladie** → mémoire. À la rencontre réelle du pathogène, l''organisme est protégé."},{"kind":"callout","tone":"warning","title_fr":"VIH et immunité","body_fr":"Le VIH attaque les LT4 auxiliaires (chefs d''orchestre de la réponse immunitaire). À terme, le système immunitaire s''effondre → SIDA → infections opportunistes."},{"kind":"checkpoint","title_fr":"Immunité","questions":[{"stem_fr":"L''immunité innée est :","choices_fr":["lente","spécifique","rapide non-spécifique","avec mémoire"],"correct_index":2,"explanation_fr":"Première ligne de défense."},{"stem_fr":"Les anticorps sont produits par :","choices_fr":["LT","LB","macrophages","érythrocytes"],"correct_index":1,"explanation_fr":"Lymphocytes B (plasmocytes)."},{"stem_fr":"La vaccination crée :","choices_fr":["immunité innée","mémoire immunitaire","inflammation","allergie"],"correct_index":1,"explanation_fr":"Préparer la réponse secondaire."}]}]}]}'::jsonb WHERE code = 'svt_immunite';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Tectonique des plaques","subtitle_fr":"Lithosphère, frontières de plaques, dorsales et subduction.","sections":[{"kind":"concept","title_fr":"Plaques et mouvements","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"La **lithosphère** (croûte + manteau supérieur, environ 100 km d''épaisseur) est fragmentée en une douzaine de **plaques tectoniques** qui se déplacent sur l''**asthénosphère** (manteau ductile)."},{"kind":"paragraph","md":"**Vitesse** : 1 à 10 cm/an typiquement. Mesurable par GPS et magnétisme."},{"kind":"paragraph","md":"**Trois types de frontières** :"},{"kind":"paragraph","md":"- **Divergente (dorsale océanique)** : les plaques s''écartent, le magma remonte → **nouvelle croûte océanique** se forme (Atlantique).\n- **Convergente (subduction)** : une plaque plonge sous l''autre → fosses océaniques, volcans, séismes profonds (chaîne andine).\n- **Transformante** : glissement latéral, sans création ni destruction de croûte (faille de San Andreas)."}]},{"kind":"concept","title_fr":"Preuves et conséquences","eyebrow_fr":"OBSERVATIONS","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"**Preuves de la dérive** : (1) **paléomagnétisme** (bandes magnétiques symétriques de part et d''autre des dorsales), (2) datation des croûtes (jeunes près des dorsales, plus vieilles loin), (3) **fossiles communs** sur des continents séparés (Mesosaurus en Afrique/Amérique du Sud)."},{"kind":"paragraph","md":"**Conséquences** : séismes (frontières actives), volcanisme (subductions et dorsales), formation des chaînes de montagnes (collisions : Himalaya = Inde + Asie)."},{"kind":"checkpoint","title_fr":"Tectonique","questions":[{"stem_fr":"Couche solide sur laquelle reposent les plaques :","choices_fr":["noyau","asthénosphère","croûte","lithosphère"],"correct_index":1,"explanation_fr":"Manteau ductile."},{"stem_fr":"À une dorsale océanique :","choices_fr":["les plaques convergent","les plaques divergent","glissement","aucun mouvement"],"correct_index":1,"explanation_fr":"Création de croûte."},{"stem_fr":"Vitesse typique d''une plaque :","choices_fr":["1-10 cm/an","1-10 m/an","1 m/s","1 cm/s"],"correct_index":0,"explanation_fr":"Vitesse géologique lente."}]}]}]}'::jsonb WHERE code = 'svt_tectonique_plaques';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Géochronologie","subtitle_fr":"Datation absolue et relative.","sections":[{"kind":"concept","title_fr":"Datation absolue","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Datation par radioactivité** : un isotope radioactif (chronomètre) se désintègre selon $N(t) = N_0 e^{-\\lambda t}$. En mesurant le rapport isotope-père / isotope-fils, on déduit l''âge."},{"kind":"paragraph","md":"**Couples utilisés selon l''âge** :"},{"kind":"paragraph","md":"- **Carbone 14** ($t_{1/2} = 5730$ ans) : matière organique, archéologie jusqu''à ~50 000 ans.\n- **Potassium-Argon** ($t_{1/2} = 1{,}25 \\times 10^9$ ans) : roches volcaniques, millions d''années.\n- **Uranium-Plomb** ($t_{1/2} = 4{,}5 \\times 10^9$ ans) : roches anciennes, jusqu''à l''âge de la Terre (4,57 Ga)."},{"kind":"formula","latex":"t = \\frac{1}{\\lambda} \\ln\\frac{N_0}{N} = \\frac{t_{1/2}}{\\ln 2} \\ln\\frac{N_0}{N}","caption_fr":"Formule de datation."}]},{"kind":"concept","title_fr":"Datation relative","eyebrow_fr":"PRINCIPES","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Sans valeur d''âge mais en relatif (avant/après) :"},{"kind":"paragraph","md":"- **Superposition** : dans une série non perturbée, les couches inférieures sont les plus anciennes.\n- **Recoupement** : une formation qui en recoupe une autre est postérieure.\n- **Identité paléontologique** : deux couches contenant les mêmes fossiles ''stratigraphiques'' sont contemporaines."},{"kind":"example","title_fr":"Datation au C14","problem_fr":"Échantillon à 25% de l''activité initiale. Âge ? (t½ = 5730)","steps_fr":["$1/4 = 1/2^2$ → 2 demi-vies.","Âge = 2 × 5730 = 11 460 ans."],"answer_fr":"≈ 11 500 ans."},{"kind":"checkpoint","title_fr":"Géochronologie","questions":[{"stem_fr":"Couple radioactif pour l''archéologie (jusqu''à 50 000 ans) :","choices_fr":["U-Pb","K-Ar","C14","Rb-Sr"],"correct_index":2,"explanation_fr":"Demi-vie 5730 ans."},{"stem_fr":"Principe de superposition dit que :","choices_fr":["les couches inférieures sont récentes","les couches inférieures sont anciennes","tout est contemporain","rien"],"correct_index":1,"explanation_fr":"Empilement chronologique."},{"stem_fr":"Âge de la Terre :","choices_fr":["4,57 milliards d''années","6000 ans","1 million d''années","13 milliards d''années"],"correct_index":0,"explanation_fr":"Datation U-Pb sur météorites."}]}]}]}'::jsonb WHERE code = 'svt_geochronologie';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Métamorphisme","subtitle_fr":"Transformation des roches sous P et T.","sections":[{"kind":"concept","title_fr":"Conditions et causes","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Le **métamorphisme** transforme une roche **à l''état solide** sous l''effet d''une augmentation de **pression** et/ou **température** (sans fusion ; au-delà, on parle de magmatisme)."},{"kind":"paragraph","md":"**Domaines de P-T** :"},{"kind":"paragraph","md":"- **Métamorphisme de contact** : forte T, faible P, autour des intrusions magmatiques.\n- **Métamorphisme régional** : grandes échelles, lors des collisions tectoniques (P et T élevées).\n- **Métamorphisme de subduction** : forte P, T modérée (HP-BT, ex. éclogites).\n- **Métamorphisme de dorsale** : P et T modérées."}]},{"kind":"concept","title_fr":"Faciès et minéraux indicateurs","eyebrow_fr":"INDICATEURS","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Les **faciès métamorphiques** (schiste vert, amphibolite, granulite, éclogite, schiste bleu) correspondent à des domaines P-T précis. Chaque faciès a des **minéraux index** caractéristiques."},{"kind":"paragraph","md":"**Lecture inverse** : la présence d''un minéral particulier dans une roche permet de déduire les conditions P-T qu''elle a subies — donc l''histoire tectonique."},{"kind":"callout","tone":"insight","title_fr":"Cycle métamorphique","body_fr":"Une roche subduite peut atteindre les conditions éclogite (>700 MPa, ~500°C), puis remonter (exhumation). Les éclogites de surface racontent une plongée passée à grande profondeur."},{"kind":"checkpoint","title_fr":"Métamorphisme","questions":[{"stem_fr":"Métamorphisme = transformation :","choices_fr":["par fusion","à l''état solide","sous l''eau seulement","par érosion"],"correct_index":1,"explanation_fr":"Sans atteindre la fusion."},{"stem_fr":"Métamorphisme de subduction est :","choices_fr":["HP-HT","BP-HT","HP-BT","BP-BT"],"correct_index":2,"explanation_fr":"Forte pression, T modérée."},{"stem_fr":"Les minéraux d''une roche métamorphique permettent de :","choices_fr":["dater","identifier P-T subies","mesurer densité","rien"],"correct_index":1,"explanation_fr":"Reconstitution thermobarométrique."}]}]}]}'::jsonb WHERE code = 'svt_metamorphisme';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Énergie cellulaire — respiration et photosynthèse","subtitle_fr":"Métabolisme énergétique, ATP.","sections":[{"kind":"concept","title_fr":"Photosynthèse","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"La **photosynthèse** transforme l''énergie lumineuse en énergie chimique (glucides). Lieu : **chloroplastes** des cellules végétales."},{"kind":"formula","latex":"6\\,\\text{CO}_2 + 6\\,\\text{H}_2\\text{O} + \\text{lumière} \\to \\text{C}_6\\text{H}_{12}\\text{O}_6 + 6\\,\\text{O}_2","caption_fr":"Bilan."},{"kind":"paragraph","md":"Deux phases : (1) **phase claire** (thylakoïdes) — la lumière dissocie l''eau et produit ATP + NADPH + O₂. (2) **phase sombre / cycle de Calvin** (stroma) — utilise ATP et NADPH pour réduire CO₂ en glucose."}]},{"kind":"concept","title_fr":"Respiration cellulaire","eyebrow_fr":"INVERSE","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\text{C}_6\\text{H}_{12}\\text{O}_6 + 6\\,\\text{O}_2 \\to 6\\,\\text{CO}_2 + 6\\,\\text{H}_2\\text{O} + \\text{ATP}","caption_fr":"Bilan inverse de la photosynthèse, dans les cellules animales et végétales."},{"kind":"paragraph","md":"Trois étapes :"},{"kind":"paragraph","md":"- **Glycolyse** (cytoplasme) : glucose → 2 pyruvate + 2 ATP + 2 NADH.\n- **Cycle de Krebs** (matrice mitochondriale) : pyruvate → CO₂ + NADH + FADH₂.\n- **Chaîne respiratoire** (membrane interne mitochondrie) : O₂ accepte les électrons, gradient de protons produit l''ATP (chimiosmose). **Bilan ~36 ATP par glucose**."},{"kind":"checkpoint","title_fr":"Énergie cellulaire","questions":[{"stem_fr":"La photosynthèse a lieu dans :","choices_fr":["mitochondries","chloroplastes","noyau","ribosomes"],"correct_index":1,"explanation_fr":"Organite spécialisé."},{"stem_fr":"Produit de la respiration cellulaire :","choices_fr":["O₂","glucose","ATP","lumière"],"correct_index":2,"explanation_fr":"Énergie utilisable par la cellule."},{"stem_fr":"Bilan ATP par glucose respiré :","choices_fr":["2","~36","100","1000"],"correct_index":1,"explanation_fr":"Glycolyse (2) + Krebs + chaîne respiratoire."}]}]}]}'::jsonb WHERE code = 'svt_energie_cellulaire';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Écosystèmes et flux d''énergie","subtitle_fr":"Producteurs, consommateurs, réseaux trophiques.","sections":[{"kind":"concept","title_fr":"Niveaux trophiques","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un **écosystème** est l''ensemble d''une **biocénose** (communauté d''êtres vivants) et de son **biotope** (milieu physique). L''énergie y circule depuis le soleil."},{"kind":"paragraph","md":"**Niveaux trophiques** :"},{"kind":"paragraph","md":"- **Producteurs (autotrophes)** : plantes, algues — captent l''énergie solaire par photosynthèse.\n- **Consommateurs primaires** (herbivores) : mangent les producteurs.\n- **Consommateurs secondaires** (carnivores I) : mangent les herbivores. Puis tertiaires, etc.\n- **Décomposeurs** : champignons, bactéries — recyclent la matière morte."}]},{"kind":"concept","title_fr":"Flux d''énergie et cycles","eyebrow_fr":"TRANSFERTS","estimated_minutes":"4","blocks":[{"kind":"callout","tone":"insight","title_fr":"Règle des 10%","body_fr":"À chaque transfert trophique, seuls ~10% de l''énergie sont transmis au niveau supérieur — le reste est dissipé en chaleur (respiration, métabolisme). C''est pourquoi les pyramides écologiques sont étroites au sommet."},{"kind":"paragraph","md":"**Cycles biogéochimiques** : la matière (C, N, P, eau) est **recyclée** entre les organismes vivants et le biotope. L''énergie, elle, est **perdue** à chaque étape (entropie)."},{"kind":"checkpoint","title_fr":"Écosystèmes","questions":[{"stem_fr":"Producteurs primaires d''un écosystème terrestre :","choices_fr":["herbivores","plantes vertes","champignons","carnivores"],"correct_index":1,"explanation_fr":"Photosynthèse → matière organique."},{"stem_fr":"Pourcentage d''énergie transmise par niveau trophique :","choices_fr":["~10%","~50%","~90%","~100%"],"correct_index":0,"explanation_fr":"Règle des 10%."},{"stem_fr":"Les décomposeurs :","choices_fr":["mangent les producteurs","recyclent la matière morte","photosynthèse","rien"],"correct_index":1,"explanation_fr":"Bouclent les cycles biogéochimiques."}]}]}]}'::jsonb WHERE code = 'svt_ecosystemes';

COMMIT;
